package ee.shop.catalog.web;

import ee.shop.catalog.repository.CategoryRepository;
import ee.shop.catalog.repository.ProductRepository;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

import java.time.format.DateTimeFormatter;
import java.time.ZoneOffset;

/**
 * robots.txt and sitemap.xml.
 *
 * Generated by the BACKEND rather than shipped as static files in the
 * frontend, for one reason: a sitemap has to list every product and category
 * URL, and those live in the database. A static file would be a snapshot that
 * goes stale the first time anyone adds a product — which is worse than no
 * sitemap, because a crawler will keep requesting URLs that 404 and will not
 * learn about the ones that exist.
 *
 * Absolute URLs are required by the sitemap protocol, so they are built from
 * app.frontend-url — the same property the OAuth redirect and password-reset
 * links use. If that is misconfigured, this is wrong too, which is the correct
 * coupling: there is exactly one notion of "where this shop lives".
 */
@RestController
@Tag(name = "Catalog")
public class SitemapController {

    private static final DateTimeFormatter W3C_DATE =
            DateTimeFormatter.ofPattern("yyyy-MM-dd").withZone(ZoneOffset.UTC);

    private final ProductRepository products;
    private final CategoryRepository categories;
    private final String siteUrl;

    public SitemapController(ProductRepository products, CategoryRepository categories,
                              @Value("${app.frontend-url}") String siteUrl) {
        this.products = products;
        this.categories = categories;
        // Trailing slash would produce "//products" in every URL.
        this.siteUrl = siteUrl.endsWith("/") ? siteUrl.substring(0, siteUrl.length() - 1) : siteUrl;
    }

    @GetMapping(value = "/robots.txt", produces = MediaType.TEXT_PLAIN_VALUE)
    @Operation(summary = "Crawler directives")
    public String robots() {
        // Everything a signed-in user sees is disallowed. Not for secrecy —
        // those endpoints all enforce their own authorization — but because
        // they are per-user or transactional pages that must never appear in
        // a search result, and crawling them wastes crawl budget on pages a
        // crawler can only ever see as a redirect to the login form.
        return """
                User-agent: *
                Disallow: /admin
                Disallow: /account
                Disallow: /orders
                Disallow: /cart
                Disallow: /checkout
                Disallow: /login
                Disallow: /register
                Disallow: /reset-password
                Disallow: /verify-email
                Disallow: /oauth/
                Disallow: /api/

                Sitemap: %s/sitemap.xml
                """.formatted(siteUrl);
    }

    @GetMapping(value = "/sitemap.xml", produces = MediaType.APPLICATION_XML_VALUE)
    @Operation(summary = "XML sitemap of public catalogue URLs")
    public String sitemap() {
        StringBuilder xml = new StringBuilder(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                        + "<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");

        // Static public pages, highest priority first.
        url(xml, "/", "1.0", null);
        url(xml, "/products", "0.9", null);
        url(xml, "/about", "0.5", null);
        url(xml, "/contacts", "0.5", null);
        url(xml, "/privacy", "0.3", null);
        url(xml, "/sales-conditions", "0.3", null);

        categories.findAll().forEach(c ->
                url(xml, "/products?categoryId=" + c.getId(), "0.7", null));

        products.findAll().stream()
                // Soft-deleted products are off the shop floor; listing them
                // would advertise URLs that 404.
                .filter(p -> !p.isDeleted())
                .forEach(p -> url(xml, "/products/" + p.getSlug(), "0.8",
                        p.getUpdatedAt() == null ? null : W3C_DATE.format(p.getUpdatedAt())));

        xml.append("</urlset>\n");
        return xml.toString();
    }

    private void url(StringBuilder xml, String path, String priority, String lastMod) {
        xml.append("  <url>\n    <loc>").append(escape(siteUrl + path)).append("</loc>\n");
        if (lastMod != null) {
            xml.append("    <lastmod>").append(lastMod).append("</lastmod>\n");
        }
        xml.append("    <priority>").append(priority).append("</priority>\n  </url>\n");
    }

    /**
     * XML-escapes a URL. Slugs are constrained to [a-z0-9-] so they cannot
     * carry markup, but category ids are interpolated too and a sitemap is a
     * document we serve to third parties — escaping at the sink is the rule
     * regardless of how trustworthy the source currently looks.
     */
    private static String escape(String s) {
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&apos;");
    }
}
